def number_of_beams(bank):
    positions = []                                                          # (row, col) of every device, in row-major order
    for i, row in enumerate(bank):
        for j, c in enumerate(row):
            if c == '1':
                positions.append((i, j))
    total = 0
    for a in range(len(positions)):
        for b in range(a + 1, len(positions)):
            r1, _ = positions[a]
            r2, _ = positions[b]
            if r1 == r2:
                continue                                                    # devices must be on different rows to form a beam
            if any(bank[k].count('1') > 0 for k in range(r1 + 1, r2)):      # check every row strictly between them for any device
                continue
            total += 1
    return total


if __name__ == "__main__":
    bank = ["011001", "000000", "010100", "001000"]
    print(number_of_beams(bank))

