import java.util.*;

public class Main {
    int numberOfBeams(String[] bank) {
        List<int[]> positions = new ArrayList<>();
        for (int i = 0; i < bank.length; i++) {
            for (int j = 0; j < bank[i].length(); j++) {
                if (bank[i].charAt(j) == '1') positions.add(new int[]{i, j});
            }
        }
        int total = 0;
        for (int a = 0; a < positions.size(); a++) {
            for (int b = a + 1; b < positions.size(); b++) {
                int r1 = positions.get(a)[0], r2 = positions.get(b)[0];
                if (r1 >= r2) continue;                                            // only count pairs with r1 < r2 once, in this fixed order
                boolean blocked = false;
                for (int k = r1 + 1; k < r2 && !blocked; k++) {
                    if (bank[k].contains("1")) blocked = true;                       // check every row strictly between them for any device
                }
                if (!blocked) total++;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        String[] bank = {"011001", "000000", "010100", "001000"};
        System.out.println(solution.numberOfBeams(bank));
    }
}

