int numberOfBeams(vector<string>& bank) {
    vector<pair<int,int>> positions;
    for (int i = 0; i < (int)bank.size(); i++) {
        for (int j = 0; j < (int)bank[i].size(); j++) {
            if (bank[i][j] == '1') positions.push_back({i, j});
        }
    }
    int total = 0;
    for (int a = 0; a < (int)positions.size(); a++) {
        for (int b = a + 1; b < (int)positions.size(); b++) {
            int r1 = positions[a].first, r2 = positions[b].first;
            if (r1 >= r2) continue;                                              // only count pairs with r1 < r2 once, in this fixed order
            bool blocked = false;
            for (int k = r1 + 1; k < r2 && !blocked; k++) {
                if (bank[k].find('1') != string::npos) blocked = true;             // check every row strictly between them for any device
            }
            if (!blocked) total++;
        }
    }
    return total;
}

int main() {
    vector<string> bank = {"011001", "000000", "010100", "001000"};
    cout << numberOfBeams(bank) << endl;
    return 0;
}

