    prev_count = 0                                                          # device count of the most recent NON-EMPTY row seen so far
    for row in bank:
        count = row.count('1')
        if count > 0:
            total += prev_count * count                                    # every pair (one from each of these two consecutive non-empty rows) forms a beam
            prev_count = count
    return total


