    int numberOfBeams(String[] bank) {
        int total = 0;
        int prevCount = 0;                                                        // device count of the most recent NON-EMPTY row seen so far
        for (String row : bank) {
            int count = 0;
            for (char c : row.toCharArray()) if (c == '1') count++;
            if (count > 0) {
                total += prevCount * count;                                         // every pair (one from each of these two consecutive non-empty rows) forms a beam
                prevCount = count;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        String[] bank = {"011001", "000000", "010100", "001000"};
        System.out.println(solution.numberOfBeams(bank));
    }
}

